// Função para armazenar a imagem em blocos de 8x8 sequencializados
//void store_image_in_blocks(uint8_t image[768][1024], int width, int height) {
void store_image_in_blocks(int width, int height, uint8_t image[height][width]) {
	if (!is_valid_image_size(width, height)) {
		return;  // Verifica se a imagem tem dimensões válidas
	}

	int block_index = 0;  // Índice para o buffer de saída

	// Percorre a imagem em blocos de 8x8
	for (int i = 0; i < height; i += BLOCK_SIZE) {
		for (int j = 0; j < width; j += BLOCK_SIZE) {
			// Percorre cada bloco de 8x8
			for (int bi = 0; bi < BLOCK_SIZE; bi++) {
				for (int bj = 0; bj < BLOCK_SIZE; bj++) {
					// Armazena o pixel no buffer de saída
					image_vector[block_index++] = image[i + bi][j + bj];
				}
			}
		}
	}
}

//void reconstruct_image_from_blocks(uint8_t image[768][1024], int width, int height) {
void reconstruct_image_from_blocks(int width, int height, uint8_t image[height][width]) {
	int block_index = 0;  // Índice para o vetor de entrada

	// Percorre a imagem em blocos de 8x8
	for (int i = 0; i < height; i += BLOCK_SIZE) {
		for (int j = 0; j < width; j += BLOCK_SIZE) {
			// Preenche cada bloco de 8x8 da imagem
			for (int bi = 0; bi < BLOCK_SIZE; bi++) {
				for (int bj = 0; bj < BLOCK_SIZE; bj++) {
					// Recupera o pixel do vetor linear e o armazena na matriz de imagem
					image[i + bi][j + bj] = image_vector[block_index++];
				}
			}
		}
	}
}

// Função que verifica se a imagem tem dimensões múltiplas de 8
int is_valid_image_size(int width, int height) {
	return (width % BLOCK_SIZE == 0 && height % BLOCK_SIZE == 0);
}

//
int rle_compress(uint8_t *input, int size, uint8_t *output) {
	int i = 0;
	int j = 0;

	while (i < size) {
		uint8_t value = input[i];
		uint8_t count = 1;

		// Conta o número de repetições consecutivas do valor atual (até 255, pois usamos uint8_t)
		while (i + 1 < size && input[i] == input[i + 1] && count < 255) {
			count++;
			i++;
		}

		// Armazena o valor e o número de repetições no vetor de saída
		output[j++] = value;
		output[j++] = count;
		i++;
	}

	// Retorna o tamanho do vetor comprimido
	return j;
}

// Função para realizar a descompressão RLE
int rle_decompress(uint8_t *compressed, int compressed_size, uint8_t *decompressed) {
	int i = 0;
	int j = 0;

	// Percorre o vetor comprimido em pares (valor, número de repetições)
	while (i < compressed_size) {
		if(j >= WIDTH *HEIGHT) //estouro de buffer
			return -1; //poderia retornar o valor do buffer (i) em que o algoritmo estava quando ocorreu o estouro
		uint8_t value = compressed[i];
		uint8_t count = compressed[i + 1];

		// Armazena o valor 'count' vezes no vetor de descompressão
		// garantindo que não haverá invasão de espaço crítico de memória
		for (int k = 0; k < count && j < WIDTH * HEIGHT; k++) {
			decompressed[j++] = value;
		}

		i += 2;  // Avança para o próximo par
	}

	// Retorna o tamanho do vetor descomprimido
	return j;
}

// Função para calcular o MSE entre duas imagens
float calculate_mse(int width, int height, uint8_t original[height][width], uint8_t processed[height][width]) {
	float mse = 0.0;
	int i, j;

	for (i = 0; i < height; i++) {
		for (j = 0; j < width; j++) {
			int diff = original[i][j] - processed[i][j];
			mse += diff * diff;
		}
	}

	mse /= (width * height);
	return mse;
}

// Função para calcular o PSNR
float calculate_psnr(int width, int height, uint8_t original[height][width], uint8_t processed[height][width]) {
	float mse = calculate_mse(width, height, original, processed);

	if (mse == 0) {
		return INFINITY;  // PSNR infinito se não houver diferença
	}

	float psnr = 10.0 * log10((255 * 255) / mse);
	return psnr;
}

//
float calculate_mean(int width, int height, uint8_t img[height][width]) {
    float sum = 0.0f;
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            sum += img[i][j];
        }
    }
    return sum / (width * height);
}

//
float calculate_variance(int width, int height, uint8_t img[height][width], float mean) {
    float variance = 0.0f;
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            float diff = img[i][j] - mean;
            // Add some debug print (if possible) or store intermediate results
            variance += diff * diff; // Instead of powf
        }
    }
    return variance / (width * height);
}

//
float calculate_covariance(int width, int height, uint8_t img1[height][width], uint8_t img2[height][width], float mean1, float mean2) {
    float covariance = 0.0f;
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            covariance += (img1[i][j] - mean1) * (img2[i][j] - mean2);
        }
    }
    return covariance / (width * height);
}

//
float calculate_ssim(int width, int height, uint8_t original[height][width], uint8_t processed[height][width]) {
    float mean_orig = calculate_mean(width, height, original);
    float mean_proc = calculate_mean(width, height, processed);

    float variance_orig = calculate_variance(width, height, original, mean_orig);
    float variance_proc = calculate_variance(width, height, processed, mean_proc);

    float covariance = calculate_covariance(width, height, original, processed, mean_orig, mean_proc);

    float ssim = ((2 * mean_orig * mean_proc + C1) * (2 * covariance + C2)) /
                 ((mean_orig * mean_orig + mean_proc * mean_proc + C1) * (variance_orig + variance_proc + C2));

    return ssim;
}

//
void write_image_blocks(uint8_t *COMPR_IMG, int input_size, NASCERR_MODE ecc, nascerr_rpt repeat) {
	//número de palavras que podem ser escritas por vez = 1024
	//input_size já será o index, número de palavras que nós teremos que escrever
	//a escrita deve levar em consideração o input_size, que será decrementado, e o tamanho máximo da memória, que será o limitante do loop
	uint32_t current_index = 0;

	while (input_size > current_index){
		//		uint16_t img_buffer[MEM_SIZE];

		int remaining_bytes = input_size - current_index;
		uint32_t block_size = (remaining_bytes >= MEM_SIZE) ? MEM_SIZE : remaining_bytes;

		for (uint16_t i = 0; i < block_size; i++){
			img_buffer[i] = (uint32_t) *(COMPR_IMG + i + current_index);
		}
		//TODO: CORRIGIR
		//Corrigir a função para função agnóstica aos dados que estão sendo escritos
		for (int i = 0; i < repeat; i++){
			nascerr_memory_write_block_cell(img_buffer, ecc, 0, block_size);
			nascerr_io_delay(1);
			nascerr_memory_read_sram_block(img_buffer, 0, ecc, block_size);
		}


		for (uint16_t i = 0; i < block_size; i++){
			*(COMPR_IMG + i + current_index) = (uint8_t) img_buffer[i];
		}
		current_index += block_size;
	}
}

//
void nascerr_image_processing(NASCERR_CTRL command, int width, int height, uint8_t image[height][width]){
	int tamanho, tamanho_res = 0;
	image_size = 2 * width * height;
	store_image_in_blocks(width, height, image);
	if (command.imagem_exp.compression == LOSSLESS){
		tamanho = rle_compress(image_vector, width * height, image_stored);
		write_image_blocks(image_stored, tamanho, command.mode, command.repeat);
		tamanho_res = rle_decompress(image_stored, tamanho, image_vector);
	}
	if (command.imagem_exp.compression == LOSS_FF){
		tamanho = width * height;
		write_image_blocks(image_vector, tamanho, command.mode, command.repeat);
	}
	if (tamanho_res == -1)
		tamanho_res++; //fazer algo com isso, caso dê erro (pode ser alterar o estado de erro, ou variável de status
	reconstruct_image_from_blocks(width, height, image_result);
	psnr = calculate_psnr(width, height, image, image_result);
	ssim = calculate_ssim(width, height, image, image_result);
	errors_corrected = nascerr_experiment_error_counter_matrix(width, height, image, image_result); //deveria ser 21904
	total_errors = nascerr_experiment_buffer_result_matrix(width, height, image, image_result, result_data); //deveria ser 0
//	total_errors = nascerr_experiment_buffer_result_matrix(width, height, image, image_result); //deveria ser 0
}

